import {
  ChangeDetectionStrategy,
  Component,
  ContentChild,
  ContentChildren,
  Directive,
  OnInit,
  QueryList,
  ViewEncapsulation,
} from '@angular/core';
import {
  _countGroupLabelsBeforeLegacyOption,
  _getLegacyOptionScrollPosition,
  MAT_LEGACY_OPTGROUP,
